const response = $input.first().json;
const formData = $('0. Form Trigger (Pick Date & Time)').first().json;

const dateStr = formData['Schedule Date'] || '';
const timeStr = formData['Schedule Time (24h format)'] || '12:00';

const scheduledTime = dateStr ? `${dateStr}T${timeStr}:00` : null;

if (!response.ok || !response.result || response.result.length === 0) {
  return [{ json: { found: false, message: 'No updates found. Forward a video to your bot first!' } }];
}

let latestVideo = null;
let latestUrl = 'No link provided';

for (const update of response.result) {
  const msg = update.message;
  if (!msg) continue;

  const textToSearch = (msg.text || '') + ' ' + (msg.caption || '');
  const urlMatch = textToSearch.match(/(https?:\/\/[^\s]+)/);
  if (urlMatch) {
    latestUrl = urlMatch[1];
  }

  if (msg.video) {
    latestVideo = {
      found: true,
      file_id: msg.video.file_id,
      file_size: msg.video.file_size || 0,
      duration: msg.video.duration || 0,
      caption: msg.caption || ''
    };
  } else if (msg.document && msg.mime_type && msg.mime_type.startsWith('video/')) {
    latestVideo = {
      found: true,
      file_id: msg.document.file_id,
      file_size: msg.document.file_size || 0,
      duration: 0,
      caption: msg.caption || ''
    };
  }
}

if (!latestVideo) {
  return [{ json: { found: false, message: 'No video found in the recent updates.' } }];
}

latestVideo.original_link = latestUrl;
latestVideo.scheduled_time = scheduledTime;

return [{ json: latestVideo }];

const uploadNode = $('6. Upload to Google Drive').first().json;
const videoData = $('2. Extract Video Info & URL').first().json;
const fileId = uploadNode.id;

if (!fileId) {
  return [{ json: { error: { message: 'No file ID from Google Drive upload', details: uploadNode } } }];
}

const directUrl = 'https://drive.google.com/uc?export=download&id=' + fileId;

return [{
  json: {
    file_url: directUrl,
    drive_file_id: fileId,
    original_link: videoData.original_link || 'No link provided',
    video_caption: videoData.caption || '',
    scheduled_time: videoData.scheduled_time,
    status: 'URL_READY'
  }
}];

