const aiData = $input.first().json;
const driveData = $('8. Build Direct Link').first().json;

let caption = '';

if (aiData && aiData.choices && aiData.choices[0] && aiData.choices[0].message && typeof aiData.choices[0].message.content === 'string') {
  caption = aiData.choices[0].message.content;
}
else if (aiData && aiData.choices && aiData.choices[0] && typeof aiData.choices[0].text === 'string') {
  caption = aiData.choices[0].text;
}
else if (aiData && typeof aiData.result === 'string') caption = aiData.result;
else if (aiData && typeof aiData.response === 'string') caption = aiData.response;
else if (aiData && typeof aiData.caption === 'string') caption = aiData.caption;
else if (aiData && typeof aiData.content === 'string') caption = aiData.content;
else if (typeof aiData === 'string') caption = aiData;

caption = (caption || '').replace(/\\n/g, '\n').replace(/\*\*/g, '').trim();

if (!caption || caption.toLowerCase().includes('not found')) {
  caption = 'Auto-posted from Telegram via Google Drive';
}

return [{
  json: {
    ...driveData,
    ai_caption: caption
  }
}];

